public class Document:Entity { public Guid UserId{get;set;} public DocumentType Type{get;set;} public string Number{get;private set;}=""; public string Status{get;set;}="Draft"; public string ClientName{get;set;}=""; public string? ClientDocument{get;set;} public string? ClientPhone{get;set;} public string? ClientEmail{get;set;} public string? ClientCity{get;set;} public DateTime IssueDate{get;set;}=DateTime.UtcNow; public DateTime? ValidUntil{get;set;} public string? Notes{get;set;} public decimal Subtotal{get;private set;} public decimal Discount{get;set;} public decimal Total{get;private set;} public string? PublicToken{get;set;} public bool PublicEnabled{get;set;} public ClientDecision ClientDecision{get;set;}=ClientDecision.Pending; public DateTime? ClientDecisionAt{get;set;} public string? ClientDecisionNote{get;set;} public string? EvidenceHash{get;set;} public Guid? OriginBudgetId{get;set;} public string? OriginBudgetNumber{get;set;} public Guid? ConvertedReceiptId{get;set;} public string? ConvertedReceiptNumber{get;set;} public List<DocumentItem> Items{get;set;}=[]; public void IssueNumber(string number){ if(!string.IsNullOrWhiteSpace(Number)) throw new InvalidOperationException("Número emitido é imutável."); Number=number; } public void CalculateTotals(){ Subtotal=Items.Sum(i=>i.CalculateTotal()); Total=Math.Max(0, Subtotal-Discount); } public Document ConvertToReceipt(string receiptNumber){ if(Type!=DocumentType.Budget||ClientDecision!=ClientDecision.Approved) throw new InvalidOperationException("Somente orçamento aprovado pode virar recibo."); var receipt=new Document{UserId=UserId,Type=DocumentType.Receipt,ClientName=ClientName,ClientDocument=ClientDocument,ClientPhone=ClientPhone,ClientEmail=ClientEmail,ClientCity=ClientCity,IssueDate=DateTime.UtcNow,Notes=Notes,OriginBudgetId=Id,OriginBudgetNumber=Number}; receipt.IssueNumber(receiptNumber); receipt.Items=Items.Select(i=>new DocumentItem{Description=i.Description,Quantity=i.Quantity,UnitPrice=i.UnitPrice,Discount=i.Discount}).ToList(); receipt.CalculateTotals(); ConvertedReceiptId=receipt.Id; ConvertedReceiptNumber=receipt.Number; Status=BudgetStatus.Converted.ToString(); return receipt; } public string GenerateEvidenceHash(string actor,string userAgent){ var payload=$"{Id}|{PublicToken}|{ClientDecision}|{ClientDecisionAt:o}|{actor}|{userAgent}|{Total}"; return EvidenceHash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(payload))); } }
public class DocumentItem:Entity { public Guid DocumentId{get;set;} public string Description{get;set;}=""; public decimal Quantity{get;set;} public decimal UnitPrice{get;set;} public decimal Discount{get;set;} public decimal Total{get;private set;} public decimal CalculateTotal()=>Total=Math.Max(0,Quantity*UnitPrice-Discount); }
public class PublicQuote:Entity { public string Token{get;set;}=new PublicToken().Value; public Guid OwnerUserId{get;set;} public Guid DocumentId{get;set;} public bool PublicEnabled{get;set;}=true; public DateTime? ExpiresAt{get;set;} public int ViewCount{get;set;} public DateTime? LastAccessAt{get;set;} public ClientDecision DecisionStatus{get;set;}=ClientDecision.Pending; public string? DecisionNote{get;set;} public DateTime? DecidedAt{get;set;} public string? DecidedByName{get;set;} public string? DecidedByDocument{get;set;} public string? DecidedByEmail{get;set;} public bool AcceptedTerms{get;set;} public string? EvidenceHash{get;set;} public string? UserAgent{get;set;} }
